template<class IteratorTy>
inline void array_pod_sort(IteratorTy Start, IteratorTy End) {


  auto NElts = End - Start;
  if (NElts <= 1) return;



  qsort(&*Start, NElts, sizeof(*Start), get_array_pod_sort_comparator(*Start));
}

