  Value *CreateOr(ArrayRef<Value*> Ops) {
    (static_cast<void> (0));
    Value *Accum = Ops[0];
    for (unsigned i = 1; i < Ops.size(); i++)
      Accum = CreateOr(Accum, Ops[i]);
    return Accum;
  }

